CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.is_vertex_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
REVOKE ALL ON FUNCTION public.is_vertex_admin() FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.is_vertex_admin() TO authenticated,service_role;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '' CHECK(length(name)<=100), preferences jsonb NOT NULL DEFAULT '{}');
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_profile ON public.profiles FOR ALL TO authenticated USING (id=auth.uid() AND public.is_vertex_admin()) WITH CHECK(id=auth.uid() AND public.is_vertex_admin());
CREATE FUNCTION public.create_vertex_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); RETURN NEW; END $$;
CREATE TRIGGER vertex_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_vertex_profile();
CREATE TABLE public.admin_leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100), company text NOT NULL DEFAULT '' CHECK(length(company)<=150), whatsapp text NOT NULL DEFAULT '' CHECK(length(whatsapp)<=25), email text NOT NULL DEFAULT '' CHECK(length(email)<=254), source text NOT NULL DEFAULT '' CHECK(length(source)<=150), stage text NOT NULL DEFAULT 'Novo' CHECK(stage IN ('Novo','Contato','Proposta','Negociação','Ganho','Perdido')), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=5000), next_contact date, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.admin_leads TO authenticated; GRANT ALL ON public.admin_leads TO service_role;
ALTER TABLE public.admin_leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_only ON public.admin_leads FOR ALL TO authenticated USING(public.is_vertex_admin()) WITH CHECK(public.is_vertex_admin());
CREATE TABLE public.admin_clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_lead_id uuid UNIQUE REFERENCES public.admin_leads(id) ON DELETE SET NULL, name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100), company text NOT NULL DEFAULT '' CHECK(length(company)<=150), contact text NOT NULL DEFAULT '' CHECK(length(contact)<=100), whatsapp text NOT NULL DEFAULT '' CHECK(length(whatsapp)<=25), email text NOT NULL DEFAULT '' CHECK(length(email)<=254), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=5000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.admin_clients TO authenticated; GRANT ALL ON public.admin_clients TO service_role;
ALTER TABLE public.admin_clients ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_only ON public.admin_clients FOR ALL TO authenticated USING(public.is_vertex_admin()) WITH CHECK(public.is_vertex_admin());
CREATE TABLE public.admin_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.admin_clients(id) ON DELETE RESTRICT, title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 150), service text NOT NULL DEFAULT '' CHECK(length(service)<=150), amount numeric(14,2) NOT NULL DEFAULT 0 CHECK(amount>=0), start_date date, due_date date, status text NOT NULL DEFAULT 'Planejamento' CHECK(status IN ('Planejamento','Em andamento','Pausado','Concluído','Cancelado')), briefing text NOT NULL DEFAULT '' CHECK(length(briefing)<=10000), url text NOT NULL DEFAULT '' CHECK(length(url)<=2048), progress integer NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100), created_at timestamptz NOT NULL DEFAULT now(), CHECK(start_date IS NULL OR due_date IS NULL OR due_date>=start_date));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.admin_projects TO authenticated; GRANT ALL ON public.admin_projects TO service_role;
ALTER TABLE public.admin_projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_only ON public.admin_projects FOR ALL TO authenticated USING(public.is_vertex_admin()) WITH CHECK(public.is_vertex_admin());
CREATE TABLE public.admin_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid REFERENCES public.admin_projects(id) ON DELETE RESTRICT, title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 150), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=5000), priority text NOT NULL DEFAULT 'Média' CHECK(priority IN ('Baixa','Média','Alta')), due_date date, status text NOT NULL DEFAULT 'Pendente' CHECK(status IN ('Pendente','Em andamento','Concluída')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.admin_tasks TO authenticated; GRANT ALL ON public.admin_tasks TO service_role;
ALTER TABLE public.admin_tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_only ON public.admin_tasks FOR ALL TO authenticated USING(public.is_vertex_admin()) WITH CHECK(public.is_vertex_admin());
CREATE TABLE public.admin_finance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL DEFAULT gen_random_uuid(), installment integer NOT NULL DEFAULT 1 CHECK(installment>=1), installments integer NOT NULL DEFAULT 1 CHECK(installments BETWEEN 1 AND 60), title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 150), kind text NOT NULL CHECK(kind IN ('Receita','Despesa')), category text NOT NULL CHECK(length(trim(category)) BETWEEN 1 AND 100), client_id uuid REFERENCES public.admin_clients(id) ON DELETE RESTRICT, project_id uuid REFERENCES public.admin_projects(id) ON DELETE RESTRICT, amount numeric(14,2) NOT NULL CHECK(amount>0), due_date date NOT NULL, paid_date date, status text NOT NULL DEFAULT 'Pendente' CHECK(status IN ('Pendente','Pago','Cancelado')), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=5000), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(group_id,installment), CHECK(installment<=installments), CHECK((status='Pago' AND paid_date IS NOT NULL) OR (status<>'Pago' AND paid_date IS NULL)));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.admin_finance TO authenticated; GRANT ALL ON public.admin_finance TO service_role;
ALTER TABLE public.admin_finance ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_only ON public.admin_finance FOR ALL TO authenticated USING(public.is_vertex_admin()) WITH CHECK(public.is_vertex_admin());
CREATE TABLE public.admin_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), singleton boolean NOT NULL DEFAULT true UNIQUE CHECK(singleton), agency_name text NOT NULL CHECK(length(trim(agency_name)) BETWEEN 1 AND 150), contact_email text NOT NULL DEFAULT '' CHECK(length(contact_email)<=254), whatsapp text NOT NULL DEFAULT '' CHECK(length(whatsapp)<=25));
GRANT SELECT,INSERT,UPDATE ON public.admin_settings TO authenticated; GRANT ALL ON public.admin_settings TO service_role;
ALTER TABLE public.admin_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_only ON public.admin_settings FOR ALL TO authenticated USING(public.is_vertex_admin()) WITH CHECK(public.is_vertex_admin());
CREATE INDEX admin_leads_stage ON public.admin_leads(stage); CREATE INDEX admin_projects_client ON public.admin_projects(client_id); CREATE INDEX admin_tasks_due ON public.admin_tasks(due_date); CREATE INDEX admin_finance_due ON public.admin_finance(due_date); CREATE INDEX admin_finance_paid ON public.admin_finance(paid_date);
CREATE FUNCTION public.convert_vertex_lead(lead_id uuid) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE l public.admin_leads; c uuid; BEGIN IF NOT public.is_vertex_admin() THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO l FROM public.admin_leads WHERE id=lead_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Lead não encontrado'; END IF; INSERT INTO public.admin_clients(source_lead_id,name,company,whatsapp,email,notes) VALUES(l.id,l.name,l.company,l.whatsapp,l.email,l.notes) ON CONFLICT(source_lead_id) DO UPDATE SET source_lead_id=EXCLUDED.source_lead_id RETURNING id INTO c; UPDATE public.admin_leads SET stage='Ganho' WHERE id=l.id; RETURN c; END $$;
REVOKE ALL ON FUNCTION public.convert_vertex_lead(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.convert_vertex_lead(uuid) TO authenticated;
CREATE FUNCTION public.create_vertex_installments(payload jsonb, quantity integer) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE g uuid := gen_random_uuid(); total_cents bigint; part_cents bigint; i integer; first_due date; BEGIN IF NOT public.is_vertex_admin() THEN RAISE EXCEPTION 'Forbidden'; END IF; IF quantity<1 OR quantity>60 THEN RAISE EXCEPTION 'Parcelas inválidas'; END IF; total_cents := round((payload->>'amount')::numeric*100); IF total_cents<quantity THEN RAISE EXCEPTION 'Valor insuficiente'; END IF; first_due := (payload->>'due_date')::date; FOR i IN 1..quantity LOOP part_cents := total_cents/quantity + CASE WHEN i<=total_cents%quantity THEN 1 ELSE 0 END; INSERT INTO public.admin_finance(group_id,installment,installments,title,kind,category,client_id,project_id,amount,due_date,paid_date,status,notes) VALUES(g,i,quantity,payload->>'title',payload->>'kind',payload->>'category',nullif(payload->>'client_id','')::uuid,nullif(payload->>'project_id','')::uuid,part_cents::numeric/100,(first_due + make_interval(months=>i-1))::date,CASE WHEN quantity=1 THEN nullif(payload->>'paid_date','')::date ELSE NULL END,CASE WHEN quantity=1 THEN payload->>'status' ELSE 'Pendente' END,coalesce(payload->>'notes','')); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.create_vertex_installments(jsonb,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_vertex_installments(jsonb,integer) TO authenticated;